(() => {
  const game = window.DRIFTWING;
  const { ctx, state } = game;
  const spawns = ctx.systems.spawns;
  window.__dwCheck = (name, ok, detail) => {
    if (!ok) console.error(`[celestial check] ${name} failed: ${detail}`);
    return `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`;
  };
  if (!spawns.debug) throw new Error('engine-celestial needs the spawns dev hook (a dev server, or a build with ?dev=1)');
  const engine = spawns.manager.registry.get('celestial');
  if (!engine) throw new Error('the celestial engine is not registered');
  const heading = state.player.heading;
  const callouts = ['{name} {distance} {direction}.', '{name} ahead, {eta}.', 'Sky check: {name}.'];
  const preset = (id, name, engines, { duration = 900, lod = { near: 3000, mid: 12000, far: 40000 }, audio = null } = {}) => Object.freeze({
    id, name, category: 'celestial', kind: 'event', rarity: 'common', heavy: false,
    candidates: { cellSize: 6000, bucketSeconds: 600, chance: 0.1 },
    filters: { biomes: null, timeOfDay: null, altitude: null, weather: null },
    engines, lod, lure: null, wind: [], audio,
    journal: { title: name, description: 'A celestial engine test fixture.' },
    discovery: { radius: 4000, requireInView: true },
    callouts,
    lifetime: { duration: [duration, duration], despawn: { distance: 20000, hysteresis: 3000, outOfViewSeconds: 30 } },
  });
  const presets = [
    preset('clMeteors', 'Test meteor shower', [{ engine: 'celestial', params: { fadeIn: 0, meteors: { radiant: { azimuth: heading, elevation: 24 }, rate: 150, fireballChance: 0.2, spread: 38, maxActive: 40 } } }], { audio: { recipe: 'meteor', params: {} } }),
    preset('clComet', 'Test comet', [{ engine: 'celestial', params: { fadeIn: 0, comet: { position: { azimuth: heading + 12, elevation: 17 }, tailLength: 24, tailWidth: 5, sidereal: false } } }]),
    preset('clEclipse', 'Test eclipse', [{ engine: 'celestial', params: { fadeIn: 0, fadeOut: 0, eclipse: { crossingSeconds: 50, totalitySeconds: 8, pathAngle: 25 } } }], { duration: 70 }),
    preset('clGlory', 'Test glory', [
      { engine: 'celestial', params: { fadeIn: 0, glory: { strength: 1, bow: 0.8 } } },
      { engine: 'weatherVolume', params: { form: 'sheet', baseMode: 'anchor', base: -320, radius: 5000, thickness: 150, puffs: 220, formSeconds: 0 } },
    ]),
    preset('clRainbow', 'Test mist rainbow', [
      { engine: 'celestial', params: { fadeIn: 0, rainbow: { radius: 420, height: 160, strength: 1.2 } } },
      { engine: 'weatherVolume', params: { form: 'mist', radius: 260, height: 420, rise: 6, puffs: 40, formSeconds: 0 } },
    ]),
  ];
  for (const entry of presets) if (!spawns.manager.getPreset(entry.id)) spawns.debug.addPreset(entry);
  window.__dwCl = { engine, events: [] };
  ctx.bus.onTyped('wildlifeQuiet', (event) => window.__dwCl.events.push({ ...event }));
  return window.__dwCheck('setup: engine registered, presets added', true, JSON.stringify({ presets: presets.map((entry) => entry.id) }));
})()

