(() => {
  const { ctx, state } = window.DRIFTWING;
  ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(28, true), { transition: 0 });
  ctx.setPhotoMode(true);
  window.__dwCl.lookAt = (direction, lift = 150) => {
    const player = state.player.position;
    const position = { x: player.x, y: player.y + lift, z: player.z };
    return ctx.systems.camera.setFreeCameraPose({ position, target: { x: position.x + direction.x * 1000, y: position.y + direction.y * 1000, z: position.z + direction.z * 1000 } });
  };
  return 'photo mode, sun at 28 degrees';
})()

(() => {
  const { ctx } = window.DRIFTWING;
  window.__dwCl.before = { sunLight: ctx.systems.sky.sunLight.intensity, birdsQuiet: ctx.systems.birds.getStats().quiet };
  const id = ctx.systems.spawns.forceSpawn('clEclipse', { distance: 0 });
  window.__dwCl.current = id;
  const part = ctx.systems.spawns.manager.getParts(id)[0];
  window.__dwCl.eclipse = part;
  // Jumps the crossing to a separation (sun radii) on the approach side.
  window.__dwCl.jump = (separation) => {
    const data = part.data;
    const params = data.params.eclipse;
    const lead = (data.duration - params.crossingSeconds) * 0.5;
    const magnitude = Math.pow(Math.max(0, separation) / 2.3, 1 / data.eclipsePower);
    data.startTime = ctx.state.time.elapsed - (lead + params.crossingSeconds * (1 - magnitude) * 0.5);
    return window.__dwCl.lookAt(ctx.state.time.sunDirection);
  };
  return JSON.stringify({ id, framed: window.__dwCl.jump(1.1), before: window.__dwCl.before });
})()

