  const player = state.player.position;
  const x = player.x + away.x * 700;
  const z = player.z + away.z * 700;
  const y = Math.max(ctx.world.groundHeight(x, z), 0);
  window.__dwCl.current = ctx.systems.spawns.manager.activate('clRainbow', { position: { x, y, z }, heading: state.player.heading, source: 'debug', force: true });
  const framed = ctx.systems.camera.setFreeCameraPose({ position: { x: player.x, y: y + 180, z: player.z }, target: { x, y: y + 260, z } });
  return JSON.stringify({ framed, ground: Math.round(y) });
})()

