(() => {
  const { ctx, state } = window.DRIFTWING;
  const memory = ctx.renderer.info.memory;
  window.__dwCl.baseline = { geometries: memory.geometries, textures: memory.textures, attributes: memory.attributes, wind: ctx.wind.sourceCount, modifiers: ctx.systems.sky.getModifierState().ids.join(',') };
  const spawns = ctx.systems.spawns;
  const player = state.player;
  // Engine CPU per frame while every component runs (the update wrapped, then restored).
  const engine = window.__dwCl.engine;
  const original = engine.update;
  const meter = { cpu: 0, frame: state.frame, time: performance.now() };
  engine.update = function measuredUpdate(instance, dt, engineCtx) {
    const start = performance.now();
    original.call(engine, instance, dt, engineCtx);
    meter.cpu += performance.now() - start;
  };
  window.__dwCl.meter = meter;
  window.__dwCl.restoreUpdate = () => { engine.update = original; };
  window.__dwCl.cycle = [
    spawns.forceSpawn('clMeteors', { distance: 0 }),
    spawns.forceSpawn('clComet', { distance: 0 }),
    spawns.forceSpawn('clEclipse', { distance: 0 }),
    spawns.manager.activate('clGlory', { position: { x: player.position.x, y: player.position.y, z: player.position.z }, heading: player.heading, source: 'debug', force: true }),
    spawns.forceSpawn('clRainbow', { distance: 700 }),
  ];
  return JSON.stringify({ baseline: window.__dwCl.baseline, cycle: window.__dwCl.cycle });
})()

(() => {
  const { ctx } = window.DRIFTWING;
  const stats = window.__dwCl.engine.stats();
  const meter = window.__dwCl.meter;
  const frames = Math.max(1, window.DRIFTWING.state.frame - meter.frame);
  const cost = { frames, cpuMsPerFrame: Math.round((meter.cpu / frames) * 1000) / 1000, frameMs: Math.round(((performance.now() - meter.time) / frames) * 100) / 100, triangles: ctx.renderer.info.render.triangles };
  window.__dwCl.restoreUpdate();
  for (const id of window.__dwCl.cycle) if (id) ctx.systems.spawns.deactivate(id, 'test');
  return JSON.stringify({ peakStats: stats, cost, modifiers: ctx.systems.sky.getModifierState().ids });
})()

